queries.sparql:
PREFIX happn: <https://example.com/happn-bank#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?customerLabel ?accountLabel ?sarLabel WHERE {
  ?rp a happn:RelatedParty ;
      happn:RelatedParty_fromCustomer ?cust ;
      happn:RelatedParty_toCustomer ?owner .
  ?bo a happn:BeneficialOwner ;
      happn:BeneficialOwner_ownerCustomer ?owner ;
      happn:BeneficialOwner_ownsAccount ?acct .
  ?sar a happn:SuspiciousActivity ;
       happn:SuspiciousActivity_flaggedAccount ?acct .
  ?cust rdfs:label ?customerLabel .
  ?acct rdfs:label ?accountLabel .
  ?sar rdfs:label ?sarLabel .
  FILTER(?customerLabel = "CU-1001")
  FILTER(?accountLabel = "AC-2013")
  FILTER(?sarLabel = "SA-001")
}

PREFIX happn: <https://example.com/happn-bank#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?boLabel ?ownerLabel WHERE {
  ?bo a happn:BeneficialOwner ;
      rdfs:label ?boLabel ;
      happn:BeneficialOwner_ownerCustomer ?owner ;
      happn:BeneficialOwner_ownsAccount ?acct .
  ?owner rdfs:label ?ownerLabel .
  ?acct rdfs:label "AC-2013" .
}

PREFIX happn: <https://example.com/happn-bank#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
ASK {
  happn:OpenSuspiciousActivity rdfs:subClassOf happn:SuspiciousActivity .
}

PREFIX happn: <https://example.com/happn-bank#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?fromLabel ?toLabel ?rtype WHERE {
  ?rp a happn:RelatedParty ;
      happn:RelatedParty_fromCustomer ?f ;
      happn:RelatedParty_toCustomer ?t ;
      happn:RelatedParty_relationship_type ?rtype .
  ?f rdfs:label ?fromLabel .
  ?t rdfs:label ?toLabel .
  FILTER(?fromLabel = "CU-1003" && ?toLabel = "CU-1008")
}
